12	/**
13	 * 审核结果与幂等去重数据访问。
14	 * 点快照以 "x,y;x,y" 文本保存，命中 zoneId 以逗号拼接，均为不可变内容。
15	 */
16	@Repository
17	public class ReviewRepository {
18	
19	    private final JdbcTemplate jdbc;
20	
21	    public ReviewRepository(JdbcTemplate jdbc) {
22	        this.jdbc = jdbc;
23	    }
