13	@Repository
14	public class AirspaceRepository {
15	
16	    private final JdbcTemplate jdbc;
17	
18	    public AirspaceRepository(JdbcTemplate jdbc) {
19	        this.jdbc = jdbc;
20	    }
21	
22	    private static final RowMapper<ZonePo> ZONE_MAPPER = (rs, n) -> new ZonePo(
23	            rs.getString("zone_id"),
24	            rs.getInt("x_min"),
25	            rs.getInt("y_min"),
26	            rs.getInt("x_max"),
27	            rs.getInt("y_max"),
28	            rs.getString("status"),
29	            rs.getLong("created_version"),
30	            (Long) rs.getObject("revoked_version"));
31	
32	    /** 读取当前全局空域版本（单行）。 */
33	    public long getGlobalVersion() {
34	        Long version = jdbc.queryForObject(
35	                "SELECT global_version FROM airspace_meta WHERE id = 1", Long.class);
36	        return version == null ? 0L : version;
37	    }
38	
39	    /** 按 zoneId 查询禁飞区，不存在返回 null。 */
40	    public ZonePo findZone(String zoneId) {
41	        try {
42	            return jdbc.queryForObject(
43	                    "SELECT zone_id, x_min, y_min, x_max, y_max, status, created_version, revoked_version "
44	                            + "FROM no_fly_zone WHERE zone_id = ?", ZONE_MAPPER, zoneId);
45	        } catch (EmptyResultDataAccessException ex) {
46	            return null;
47	        }
48	    }
49	
50	    /** 查询全部有效（ACTIVE）禁飞区。 */
51	    public List<ZonePo> findActiveZones() {
52	        return jdbc.query(
53	                "SELECT zone_id, x_min, y_min, x_max, y_max, status, created_version, revoked_version "
54	                        + "FROM no_fly_zone WHERE status = 'ACTIVE' ORDER BY zone_id",
55	                ZONE_MAPPER);
56	    }
57	
58	    /** 创建禁飞区（调用方负责事务与版本递增）。 */
59	    public void insertZone(ZonePo zone) {
60	        jdbc.update("INSERT INTO no_fly_zone "
61	                        + "(zone_id, x_min, y_min, x_max, y_max, status, created_version, revoked_version) "
62	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
63	                zone.zoneId(), zone.xMin(), zone.yMin(), zone.xMax(), zone.yMax(),
64	                zone.status(), zone.createdVersion(), zone.revokedVersion());
65	    }
66	
67	    /** 撤销禁飞区并记录撤销生效版本（调用方负责事务与版本递增）。 */
68	    public void markRevoked(String zoneId, long revokedVersion) {
69	        jdbc.update("UPDATE no_fly_zone SET status = 'REVOKED', revoked_version = ? "
70	                + "WHERE zone_id = ? AND status = 'ACTIVE'", revokedVersion, zoneId);
71	    }
72	
73	    /**
74	     * 在当前事务内对协调锁行做真实更新（touched 加一）取得行级排他锁，并读取空域版本。
75	     *
76	     * <p>必须更新为不同的值，数据库才不会跳过加锁；该锁在 H2（MVStore）与
77	     * MySQL InnoDB 下都确定持有至事务提交。审核事务持锁期间，任何禁飞区
78	     * 创建/撤销事务（同样先更新该行）都无法提交，保证审核读到的版本号与
79	     * 全部禁飞区来自同一个已提交状态。</p>
80	     */
81	    public long getGlobalVersionForUpdate() {
82	        jdbc.update("UPDATE coord_lock SET touched = touched + 1 WHERE id = 1");
83	        return getGlobalVersion();
84	    }
85	
86	    /**
87	     * 原子地将全局空域版本加一并返回新版本。
88	     * 先更新协调锁行（与审核事务互斥），再推进版本；必须在业务事务内调用，
89	     * 保证区域变更、版本推进与去重记录原子提交，且不会产生
90	     * “携带新版本、使用旧区域”的结论。
91	     */
92	    public long incrementGlobalVersion() {
93	        jdbc.update("UPDATE coord_lock SET touched = touched + 1 WHERE id = 1");
94	        jdbc.update("UPDATE airspace_meta SET global_version = global_version + 1 WHERE id = 1");
95	        return getGlobalVersion();
96	    }
97	}
