526	    // 稳定性复核轮：同键并发场景多次验证均要求恰好一次业务生效
527	    @Test
528	    void concurrentSameRequestIdPlaysBackOneOutcome() throws Exception {
529	        // 同键同参并发：只能有一次业务生效，另一方重放同一结果
530	        String requestId = "concurrent-same-key";
531	        int n = 6;
532	        CyclicBarrier barrier = new CyclicBarrier(n);
533	        ExecutorService pool = Executors.newFixedThreadPool(n);
534	        try {
535	            List<Future<MutationResponse>> futures = new java.util.ArrayList<>();
536	            for (int i = 0; i < n; i++) {
537	                futures.add(pool.submit(() -> {
538	                    barrier.await(5, TimeUnit.SECONDS);
539	                    return service.createZone(
540	                            new ZoneCreateRequest("ck", 0, 0, 10, 10, requestId));
541	                }));
542	            }
543	            int firstCount = 0;
544	            int replayCount = 0;
545	            for (Future<MutationResponse> f : futures) {
546	                MutationResponse resp = f.get(15, TimeUnit.SECONDS);
547	                if (resp.replayed()) {
548	                    replayCount++;
549	                } else {
550	                    firstCount++;
551	                }
552	            }
553	            assertEquals(1, firstCount, "仅一次请求真正执行业务");
554	            assertEquals(n - 1, replayCount);
555	            assertEquals(1, jdbc.queryForObject("SELECT COUNT(*) FROM no_fly_zone", Integer.class));
556	            assertEquals(1, jdbc.queryForObject(
557	                    "SELECT COUNT(*) FROM request_dedup WHERE request_id = ?", Integer.class, requestId));
558	            // 同键异参事后仍 409
559	            ApiException ex = assertThrows(ApiException.class, () -> service.createZone(
560	                    new ZoneCreateRequest("ck", 1, 1, 12, 12, requestId)));
561	            assertEquals(HttpStatus.CONFLICT, ex.status());
562	        } finally {
563	            pool.shutdownNow();
564	        }
565	    }
