            rs.getLong("window_start_min"),
            rs.getLong("window_end_min"),
            rs.getInt("capacity"),
            rs.getLong("created_at"));

    private static final RowMapper<OccupancyPo> OCCUPANCY_MAPPER = (rs, n) -> new OccupancyPo(
            rs.getString("bucket_key"),
