            rs.getString("review_id"),
            rs.getString("priority"),
            rs.getString("event_no"),
            rs.getString("status"),
            rs.getLong("created_at"));

    private static final RowMapper<PreemptionPo> PREEMPTION_MAPPER = (rs, n) -> new PreemptionPo(
            rs.getString("preemption_id"),
